383	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: V CSR reads issued after GPR reads")
384	{
385	  RecordingBus bus;
386	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
387	
388	  hybrid_state_v1 input{};
389	  input.magic   = HYBRID_STATE_MAGIC;
390	  input.version = HYBRID_STATE_VERSION;
391	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
392	  input.priv    = 3;
393	
394	  hybrid::StateDrain drain(bus, kScratch);
395	  (void) drain.drain_with_passthrough(input);
396	
397	  // Find the last GPR COMMAND read and the first V CSR COMMAND read.
398	  std::optional<std::size_t> last_gpr_cmd;
399	  std::optional<std::size_t> first_vcsr_cmd;
400	  const std::initializer_list<uint16_t> vcsr_regnos = {
401	    hybrid::regno_csr(RD::kCsrVstart),
402	    hybrid::regno_csr(RD::kCsrVxsat),
403	    hybrid::regno_csr(RD::kCsrVxrm),
404	    hybrid::regno_csr(RD::kCsrVcsr),
405	    hybrid::regno_csr(RD::kCsrVtype),
406	    hybrid::regno_csr(RD::kCsrVl),
407	  };
408	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
409	    const auto& op = bus.ops[i];
410	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
411	    const uint16_t regno = op.value & 0xFFFFu;
412	    // Only register READS matter here. The V-data dump sweep also issues GPR
413	    // WRITES (x5/x6/x7 scratch) at the end of drain; those are not the
414	    // architectural GPR reads this ordering check is about.
415	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
416	    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
417	      last_gpr_cmd = i;
418	    for (uint16_t vcsr : vcsr_regnos)
419	      if (is_read && !first_vcsr_cmd && regno == vcsr)
420	        first_vcsr_cmd = i;
421	  }
422	  REQUIRE(last_gpr_cmd.has_value());
423	  REQUIRE(first_vcsr_cmd.has_value());
424	  CHECK(*last_gpr_cmd < *first_vcsr_cmd);
425	}
