457	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
458	          "after the architectural counter/CSR reads")
459	{
460	  RecordingBus bus;
461	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
462	
463	  hybrid_state_v1 input{};
464	  input.magic   = HYBRID_STATE_MAGIC;
465	  input.version = HYBRID_STATE_VERSION;
466	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
467	  input.priv    = 3;
468	  input.vlenb   = 64;
469	
470	  hybrid::StateDrain drain(bus, kScratch);
471	  (void) drain.drain_with_passthrough(input);
472	
473	  // (a) all 32 registers are dumped as 4 LMUL=8 groups: one vse8.v per group
474	  //     base (v0/v8/v16/v24) covers 8 registers, landing in any progbuf slot of
475	  //     the single grouped Program-Buffer execution.
476	  std::vector<int> missing;
477	  std::optional<std::size_t> first_vse_idx;
478	  for (uint16_t g = 0; g < 32; g += 8) {
479	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(g), 7);
480	    std::optional<std::size_t> at;
481	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
482	      const auto& op = bus.ops[i];
483	      if (op.kind == DmiOp::Kind::Write
484	          && op.reg >= hybrid::kProgbuf0
485	          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
486	          && op.value == want) { at = i; break; }
487	    }
488	    if (!at) { missing.push_back(g); continue; }
489	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
490	  }
491	  CHECK(missing.empty());
492	  REQUIRE(first_vse_idx.has_value());
493	
494	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
495	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
496	  //     counters. minstret(0xB02) is the last counter read before the sweep.
497	  std::optional<std::size_t> minstret_read_idx;
498	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
