670	// #1 (drain-minimal): when --verify is off the driver consumes only the vsim
671	// mcycle delta, so the full register-file readback (~190 DMI abstract commands)
672	// is wasted. drain_counters_only refreshes mcycle+minstret from the hart and
673	// passes every other field through from the QEMU1 snapshot, issuing exactly two
674	// abstract-command reads.
675	TEST_CASE("drain_counters_only refreshes only mcycle+minstret, preserves passthrough")
676	{
677	  RecordingBus bus;
678	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
679	  bus.regfile[hybrid::regno_csr(RD::kCsrMcycle)]   = 0xABCD1234ULL;
680	  bus.regfile[hybrid::regno_csr(RD::kCsrMinstret)] = 0x56789ABCULL;
681	
682	  // Passthrough input (QEMU1 snapshot) with distinctive non-counter fields.
683	  hybrid_state_v1 input{};
684	  input.magic   = HYBRID_STATE_MAGIC;
685	  input.version = HYBRID_STATE_VERSION;
686	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V
687	                  | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
688	  input.priv    = 3;
689	  for (uint16_t i = 0; i < 32; ++i) {
690	    input.gpr[i] = 0x1000ULL + i;
691	    input.fpr[i] = 0x2000ULL + i;
692	  }
693	  input.mstatus        = 0xDEADULL;
694	  input.andes.mxstatus = 0xBEEFULL;
695	  input.m_ext.menvcfg  = 0xCAFEULL;
696	  input.mcycle = input.minstret = 0;  // stale -- must be overwritten by the read
697	
698	  hybrid::StateDrain drain(bus, kScratch);
699	  const auto out = drain.drain_counters_only(input);
700	
701	  // Counters refreshed from the hart.
702	  CHECK(out.mcycle   == 0xABCD1234ULL);
703	  CHECK(out.minstret == 0x56789ABCULL);
704	  // Every other field passes through untouched (no DMI read issued for it).
705	  CHECK(out.mstatus        == 0xDEADULL);
706	  CHECK(out.andes.mxstatus == 0xBEEFULL);
707	  CHECK(out.m_ext.menvcfg  == 0xCAFEULL);
708	  for (uint16_t i = 1; i < 32; ++i) {
709	    CHECK(out.gpr[i] == 0x1000ULL + i);
710	    CHECK(out.fpr[i] == 0x2000ULL + i);
711	  }
712	
713	  // The whole point of #1: the ONLY abstract-command reads are the two
714	  // counters -- no GPR/FPR/CSR register-file readback.
715	  int reads = 0, mcycle_reads = 0, minstret_reads = 0;
716	  for (const auto& op : bus.ops) {
717	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
718	    const bool is_write = ((op.value >> 16) & 1u) != 0;
719	    if (is_write) continue;
720	    const uint16_t regno = op.value & 0xffffu;
721	    ++reads;
722	    if (regno == hybrid::regno_csr(RD::kCsrMcycle))   ++mcycle_reads;
723	    if (regno == hybrid::regno_csr(RD::kCsrMinstret)) ++minstret_reads;
724	    CHECK(regno < 0x1000u);  // never a GPR (>=0x1000) nor FPR (>=0x1020)
725	  }
726	  CHECK(reads == 2);
727	  CHECK(mcycle_reads == 1);
728	  CHECK(minstret_reads == 1);
