742	    bus.regfile[hybrid::regno_gpr(i)] = 0xC0000000ULL + i;
743	  for (uint16_t i = 0; i < 32; ++i)
744	    bus.regfile[hybrid::regno_fpr(i)] = 0xD0000000ULL + i;
745	  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;
