765	  // no L2C there is nothing the abstract command space cannot reach.
766	  for (const auto& op : bus.ops)
767	    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
768	                 && op.value == hybrid::kExecProgbufCmd));
