812	// ---- v5: L2C MMIO config read-back -----------------------------------------
813	// The dual of ResumeDriver::restore_l2c: re-read the writable L2C config
814	// registers via Program-Buffer word loads so the --verify oracle sees the
815	// round-tripped values, not the stale QEMU1 passthrough. Gated on the engine
816	// having an L2C (set_l2c); a load from an absent region would fault the PB.
817	
818	static std::size_t count_pb_insn(const std::vector<DmiOp>& ops, uint32_t insn)
819	{
820	  std::size_t n = 0;
821	  for (const auto& op : ops)
822	    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
823	        && op.value == insn)
824	      ++n;
825	  return n;
826	}
